/// <summary>
/// PricingAttribute of table <c>RetailLoyaltyCard</c> field LoyaltyEnrollmentDate.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailLoyaltyCardLoyaltyEnrollmentDate extends UPSPricingAttributeRetailLoyaltyCard implements UPSIPricingAttribute
{
}

