public str getName()
{
    return fieldPName(RetailLoyaltyCard, LoyaltyEnrollmentDate);
}

public Set getAllowedValues()
{
    RetailLoyaltyCard   retailLoyaltyCard;
    var                 ret = new Set(Types::Date);

    while select LoyaltyEnrollmentDate from retailLoyaltyCard
        group by LoyaltyEnrollmentDate
    {
        ret.add(retailLoyaltyCard.LoyaltyEnrollmentDate);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailLoyaltyCard, LoyaltyEnrollmentDate));
    qbr.value(queryValue(_value));
}
